query:
CREATE TABLE `collections` (
	`id` int AUTO_INCREMENT NOT NULL,
	`userId` int NOT NULL,
	`name` varchar(255) NOT NULL,
	`description` text,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	`updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `collections_id` PRIMARY KEY(`id`)
);
CREATE TABLE `resource_tags` (
	`id` int AUTO_INCREMENT NOT NULL,
	`resourceId` int NOT NULL,
	`tagId` int NOT NULL,
	CONSTRAINT `resource_tags_id` PRIMARY KEY(`id`)
);
CREATE TABLE `resources` (
	`id` int AUTO_INCREMENT NOT NULL,
	`userId` int NOT NULL,
	`collectionId` int,
	`title` varchar(255) NOT NULL,
	`description` text,
	`contentType` enum('link','text') NOT NULL,
	`content` text NOT NULL,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	`updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `resources_id` PRIMARY KEY(`id`)
);
CREATE TABLE `tags` (
	`id` int AUTO_INCREMENT NOT NULL,
	`userId` int NOT NULL,
	`name` varchar(100) NOT NULL,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `tags_id` PRIMARY KEY(`id`)
);
CREATE INDEX `collections_userId_idx` ON `collections` (`userId`);
CREATE INDEX `resource_tags_resourceId_idx` ON `resource_tags` (`resourceId`);
CREATE INDEX `resource_tags_tagId_idx` ON `resource_tags` (`tagId`);
CREATE INDEX `resources_userId_idx` ON `resources` (`userId`);
CREATE INDEX `resources_collectionId_idx` ON `resources` (`collectionId`);
CREATE INDEX `tags_userId_idx` ON `tags` (`userId`);
CREATE INDEX `tags_userId_name_idx` ON `tags` (`userId`,`name`);

